"""Plain-language operator view. Presentation only; server controls remain authoritative."""
PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Gateway care</title><style>
:root{color-scheme:light;--ink:#18312c;--muted:#60726c;--line:#dce6df;--green:#12644d;--paper:#f4f7f3}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,sans-serif}header,main,#login,#message,footer{max-width:1120px;margin:auto;padding:20px 28px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{font-weight:750;letter-spacing:-.5px;font-size:22px}a{color:var(--green)}nav{display:flex;gap:22px}h1{font-size:clamp(30px,4vw,46px);line-height:1.15;letter-spacing:-1.5px;margin:12px 0}h2{font-size:23px;margin:0 0 12px}h3{font-size:18px;margin:0 0 10px}h4{margin:16px 0 6px}p{margin:8px 0}.muted,small{color:var(--muted)}.eyebrow{text-transform:uppercase;letter-spacing:1.7px;font-size:12px;font-weight:750;color:var(--green)}.hero{padding:18px 0 24px;max-width:770px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card,.panel{background:white;border:1px solid var(--line);border-radius:16px;padding:22px;margin-bottom:18px}.card strong{display:block;font-size:23px;margin-top:10px}.good{border-left:5px solid #23815d}.warn{border-left:5px solid #bd7c13}.bad{border-left:5px solid #bb4d42}.section-head{display:flex;justify-content:space-between;align-items:center;margin:24px 0 12px}.pill{display:inline-block;border-radius:30px;padding:4px 12px;background:#e5eee7;font-size:13px;font-weight:650}.steps{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}.steps b{display:block;margin-bottom:5px}details{border-top:1px solid var(--line);padding-top:14px;margin-top:16px}summary{cursor:pointer;font-weight:650}button,.button{background:var(--green);color:white;border:1px solid var(--green);border-radius:8px;padding:11px 16px;font:inherit;font-weight:650;cursor:pointer;display:inline-block;text-decoration:none;margin:10px 8px 2px 0}button.secondary{background:white;color:var(--green)}button:disabled{opacity:.5;cursor:default}label{display:block;font-weight:600;margin:14px 0 5px}input,textarea,select{font:inherit;display:block;width:100%;padding:11px;border:1px solid #a8b9b0;border-radius:7px;background:white;color:var(--ink)}textarea{min-height:84px;resize:vertical}input[type=file]{margin-top:10px}#message{padding-top:6px;padding-bottom:6px;font-size:14px}#message:empty{display:none}#message.error{color:#a3342b}ul{padding-left:22px}li{margin:7px 0}pre{font-size:12px;overflow:auto;max-height:350px;white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7f3;padding:14px;border-radius:8px}.row{border-bottom:1px solid var(--line);padding:14px 0}.row:last-child{border:0}footer{font-size:13px;color:var(--muted)}[hidden]{display:none!important}:focus-visible{outline:3px solid #b87712;outline-offset:3px}@media(max-width:700px){.grid,.steps{grid-template-columns:1fr}header,main,#login,#message,footer{padding:16px}nav{gap:12px;font-size:14px}.card{margin-bottom:0}.grid{margin-bottom:20px}}
</style></head><body><header><span class="brand">Gateway care<span class="muted"> / HAProxy lab</span></span><nav><a href="#guide">How it works</a><a href="http://localhost:3000/d/platform-mapek?from=now-15m&amp;to=now">Monitoring </a></nav></header>
<section id="login"><div class="hero"><span class="eyebrow">Operator access</span><h1>Keep requests flowing.</h1><p>See whether the gateway is working, understand an incident and review a safe repair.</p></div><div class="panel"><h2>Sign in with your access file</h2><p>Choose the <b>operator.token</b> file saved on your laptop. No username is needed. The file is used only to sign in to this healer.</p><label for="tokenfile">Access file<input id="tokenfile" type="file" accept=".token,text/plain"></label><details><summary>Paste an access token instead</summary><label for="token">Access token<input id="token" type="password" autocomplete="current-password"></label><button id="sign">Sign in</button></details></div></section>
<p id="message" role="status" aria-live="polite"></p><main id="content" hidden>
<div class="hero"><span class="eyebrow">Service overview</span><h1>Is the gateway working?</h1><p>HAProxy forwards requests to a backend service. This healer can temporarily increase its outgoing port capacity when that specific limit causes requests to fail.</p><small id="updated">Waiting for the first update...</small></div>
<div class="grid" id="health"></div><div class="section-head"><h2>What needs your attention</h2><span class="pill" id="attention-count"></span></div><div id="incidents"></div>
<section class="panel" id="guide"><h2>What happens when something goes wrong?</h2><div class="steps"><div><b>1  /  Watch</b><small>A separate client sends real test requests.</small></div><div><b>2  /  Understand</b><small>The healer checks whether outgoing ports caused the failure.</small></div><div><b>3  /  Decide</b><small>You approve a known repair, or investigate an unknown problem.</small></div><div><b>4  /  Check</b><small>Successful requests must prove that the repair worked.</small></div><div><b>5  /  Remember</b><small>Two verified incidents and your review can qualify future reuse.</small></div></div><details><summary>What can and cannot be repaired?</summary><p>The qualified repair temporarily expands the gateway namespace's outgoing port range from 32 to 256 ports. It does not restart HAProxy. The healer refuses this change when the backend is unhealthy, memory is unsafe, reserved ports conflict or evidence is missing.</p><p>Other problems require investigation. AI can suggest checks but cannot authorise or perform a repair. This is a research lab with synthetic requests, not a production banking platform.</p></details></section>
<details class="panel" id="history-section"><summary>Past incidents <span class="muted">- outcomes and investigation notes</span></summary><div id="history"></div></details>
<details class="panel" id="settings-section"><summary>Automation settings <span class="muted">- choose when the healer may act</span></summary><div id="modes"></div><h3>Remembered repair for this gateway</h3><div id="procedures"></div></details>
<details class="panel"><summary>Technical evidence and audit</summary><p>For troubleshooting and research. These records are not instructions to run.</p><h3>Latest measurements</h3><pre id="observations"></pre><h3>Recent repair execution</h3><pre id="executions"></pre><h3>Recent audit events</h3><pre id="audit"></pre></details>
</main><footer>MAPE-K research prototype  /  Monitoring, analysis, planning, execution and recorded knowledge.</footer><script>
const $=id=>document.getElementById(id);const drafts={};let busy=false;let failed=false;
const titles={gateway_outbound_port_exhaustion:'Outgoing connection capacity is exhausted',gateway_dependency_unavailable:'The backend service is unavailable',gateway_unsafe_headroom:'Memory is too low for a safe repair',gateway_reserved_port_conflict:'The port change conflicts with a reservation',gateway_investigation_required:'Requests failed; the cause needs investigation',unknown:'There is not enough reliable evidence'};
const explanations={gateway_outbound_port_exhaustion:'Requests could not get an outgoing source port. The backend was healthy, so a bounded capacity increase may help.',gateway_dependency_unavailable:'The independent backend check failed. Adding outgoing ports will not fix a backend outage.',gateway_unsafe_headroom:'The host needs more free memory before the port repair can be considered.',gateway_reserved_port_conflict:'The proposed range overlaps reserved ports. An operator must investigate; the healer will not bypass the reservation.',gateway_investigation_required:'The available checks do not establish a port-capacity fault. Investigate before changing anything.',unknown:'Check the agent and independent client. Missing or stale readings are not proof that the service is healthy.'};
const statuses={pending:'Awaiting review',approved:'Approved; waiting for safety checks',executing:'Repair in progress',verified:'Repair verified',failed:'Repair was not verified',resolved:'Symptoms cleared; no further action pending'};
const modeLabels={observe:'Watch only',reviewed:'Ask before repairing',automatic:'Reuse reviewed repairs'};
function text(parent,tag,value,cls){const el=document.createElement(tag);el.textContent=value;if(cls)el.className=cls;parent.append(el);return el}
function details(parent,title,key){const el=document.createElement('details');el.dataset.key=key;text(el,'summary',title);parent.append(el);return el}
function field(parent,label,key,multi=false){const id='field-'+key;const lab=text(parent,'label',label);lab.htmlFor=id;const el=document.createElement(multi?'textarea':'input');el.id=id;el.value=drafts[key]||'';el.oninput=()=>drafts[key]=el.value;parent.append(el);return el}
function button(parent,label,handler,secondary=false){const el=text(parent,'button',label,secondary?'secondary':'');el.onclick=handler;return el}
function problem(message){$('message').textContent=message;$('message').className='error'}
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(r.status===401){$('login').hidden=false;$('content').hidden=true}if(!r.ok){const error=Error(v.error||'Request refused');error.status=r.status;throw error}return v}
async function decision(path,data){if(busy)return;busy=true;try{await api(path,data);$('message').textContent='Your decision was recorded.';$('message').className='';await refresh()}catch(e){problem(e.message)}finally{busy=false}}
async function signIn(token){try{await api('/login',{token});$('token').value='';$('message').textContent='';$('message').className='';await refresh()}catch(e){problem(e.message)}}
$('sign').onclick=()=>signIn($('token').value);$('tokenfile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>512){problem('Choose the small operator.token file, not a backup archive.');e.target.value='';return}const token=(await f.text()).trim();e.target.value='';await signIn(token)};
function parsed(value){try{return JSON.parse(value)}catch{return {}}}
function currentRows(s){return s.incidents.filter(i=>s.policies[parsed(i.before).target])}
function sameTarget(s,i){const before=parsed(i.before);const sample=s.observations[before.target]?.sample;return !sample?.identity||before.identity===sample.identity}
function actor(parent,key){return field(parent,'Your name (recorded with this decision)',key)}
function aiReport(parent,s,item,closed){const found=(s.investigations||[]).find(r=>r.incident===item.id);if(closed&&!found)return;const section=details(parent,found?.status==='complete'?'Read the AI investigation':'Investigate with AI','ai-'+item.id);
 text(section,'p','AI suggests possible causes and checks. It can be wrong and cannot approve or run a repair. Its report describes the observations submitted at the time.','muted');
 if(found?.status==='complete'){const data=parsed(found.advice);if(data.safety_context){text(section,'h4','Safety checks from the healer');for(const note of data.safety_context.constraints||[])text(section,'p',note)}
 const report=data.report||{};if(!data.guidance_version)text(section,'p','This saved report uses earlier guidance and may contain outdated advice. It is not a current diagnosis.','muted');text(section,'h4','AI summary');text(section,'p',report.summary||'No summary available.');for(const [key,label] of [['hypotheses','Possible causes - not confirmed'],['operator_checks','Checks for the operator'],['missing_evidence','What is still unknown'],['proposed_remediation','Possible next steps - require review'],['verification','How to check recovery'],['rollback','How to undo a change safely']]){if(report[key]?.length){const d=details(section,label,'ai-'+key+'-'+item.id);const ul=text(d,'ul','');for(const value of report[key])text(ul,'li',value)}}
 }else if(found?.status==='running')text(section,'p','The investigation is running. This page will update when it is ready.');
 else if(!closed){if(found?.status==='unavailable')text(section,'p','The last AI request was unavailable. Continue manually or retry.');const name=actor(section,'ai-'+item.id);button(section,'Ask AI for an explanation',()=>decision('/api/investigate',{incident:item.id,actor:name.value}),true)}
 else text(section,'p','No AI report was requested for this past incident.');
}
function incident(parent,s,item,closed=false){const card=text(parent,'article','',closed?'row':'panel warn');const pastTitles={gateway_outbound_port_exhaustion:'Port-capacity incident',gateway_dependency_unavailable:'Backend outage',gateway_unsafe_headroom:'Low memory headroom',gateway_reserved_port_conflict:'Port reservation conflict',gateway_investigation_required:'Unexplained request failure',unknown:'Missing or stale readings'};text(card,'h3',(closed?pastTitles:titles)[item.cause]||'Gateway incident');text(card,'p',(statuses[item.status]||item.status)+'  /  '+new Date(item.opened*1000).toLocaleString(),'muted');if(!closed)text(card,'p',explanations[item.cause]||'Inspect the recorded evidence before choosing a repair.');
 if(!closed){if(item.status==='pending'&&item.action){const policy=s.policies[parsed(item.before).target];text(card,'h4','Proposed repair');text(card,'p','Temporarily increase outgoing port capacity from 32 to 256 ports. The gateway stays running. Fresh successful requests must verify recovery; rollback waits for safe conditions.');
 if(policy.mode==='observe')text(card,'p','Watch-only mode is active. Open Automation settings to allow reviewed repairs.');else{const name=actor(card,'approve-'+item.id);const reason=field(card,'Why is this repair appropriate?','reason-'+item.id,true);button(card,'Approve this temporary repair',()=>decision('/api/approve',{incident:item.id,actor:name.value,reason:reason.value}))}}
 else if(item.status==='pending')text(card,'p','No automatic repair is available for this evidence. Use the investigation steps below.');else if(item.status==='executing')text(card,'p','The healer is checking real requests. A successful configuration change alone does not count as recovery.');
 }
 aiReport(card,s,item,closed);
 const records=(s.human_repairs||[]).filter(r=>r.incident===item.id);if(!closed||records.length){const manual=details(card,'Record or review a manual repair','manual-'+item.id);for(const r of records){text(manual,'p',r.actor+' reported: '+r.detail);text(manual,'p','Reported check: '+r.verification)}if(!closed){text(manual,'p','Use this after you make a change through administrator access. This note does not qualify an automatic repair.');const name=actor(manual,'manual-'+item.id),repair=field(manual,'What did you change?','repair-'+item.id,true),check=field(manual,'How did you check the result?','check-'+item.id,true);button(manual,'Save the repair note',()=>decision('/api/human-repair',{incident:item.id,actor:name.value,detail:repair.value,verification:check.value}),true)}}
 const evidence=details(card,'Technical evidence for this incident','evidence-'+item.id);text(evidence,'pre',JSON.stringify({before:parsed(item.before),after:item.after?parsed(item.after):null},null,2));
}
function render(s){const open=new Set([...document.querySelectorAll('details[open][data-key]')].map(e=>e.dataset.key));const rows=currentRows(s);const active=rows.filter(i=>sameTarget(s,i)&&['pending','approved','executing','failed'].includes(i.status));const parent=$('health');parent.replaceChildren();
 const target=Object.keys(s.policies)[0],value=s.observations[target],sample=value?.sample,m=sample?.metrics||{};const fresh=!!sample?.identity&&sample.supported===true&&!sample.error&&Date.now()/1000-sample.time<=10&&Date.now()/1000-sample.time>=-2;
 const card=(label,status,description,tone)=>{const c=text(parent,'section','','card '+tone);text(c,'span',label,'muted');text(c,'strong',status);text(c,'p',description)};
 card('Independent request check',fresh?(m.client_transaction_ok===true?'Requests are succeeding':m.client_transaction_ok===false?'Requests are failing':'Not known'):'Not known',fresh?'A separate client checks the response through HAProxy.':'Fresh evidence is unavailable. Do not assume the service is healthy.',fresh&&m.client_transaction_ok===true?'good':'warn');
 card('Healer control',modeLabels[s.policies[target]?.mode]||'Not known',s.policies[target]?.mode==='automatic'?'Only previously reviewed repairs for this exact gateway may run automatically.':s.policies[target]?.mode==='reviewed'?'You must approve an eligible repair before it runs.':'The healer observes and records; it does not execute repairs.','');
 card('Backend service',fresh?(m.upstream_healthy===true?'Responding':m.upstream_healthy===false?'Unavailable':'Not known'):'Not known','A separate check distinguishes a backend outage from a port-capacity problem.',fresh&&m.upstream_healthy===true?'good':'warn');
 $('updated').textContent='Live view  /  updated '+new Date().toLocaleTimeString();$('attention-count').textContent=active.length?active.length+' to review':'No open incidents';if(document.activeElement?.closest('#content input,#content textarea'))return;
 $('incidents').replaceChildren();if(!active.length){const c=text($('incidents'),'section','','panel '+(fresh&&m.client_transaction_ok===true?'good':'warn'));text(c,'h3',fresh&&m.client_transaction_ok===true?'Nothing needs a repair right now':'Check the latest service readings');text(c,'p',fresh&&m.client_transaction_ok===true?'The independent request check is passing. Monitoring continues in the background.':'There is no current incident awaiting a decision, but service health is not confirmed.');}for(const i of active.reverse())incident($('incidents'),s,i);
 $('history').replaceChildren();const archived=rows.filter(i=>!active.includes(i)).reverse();text($('history'),'p','Showing the latest 10 of '+archived.length+' past records. Older experiment data remains in the technical audit and private backups.','muted');for(const i of archived.slice(0,10))incident($('history'),s,i,true);
 $('modes').replaceChildren();for(const [id,p] of Object.entries(s.policies)){text($('modes'),'p','Current setting: '+modeLabels[p.mode]);const name=actor($('modes'),'mode-'+id),reason=field($('modes'),'Reason for changing the setting','mode-reason-'+id,true);for(const [mode,label] of Object.entries(modeLabels)){const b=button($('modes'),label,()=>decision('/api/mode',{target:id,mode,actor:name.value,reason:reason.value}),true);b.disabled=p.mode===mode}}
 $('procedures').replaceChildren();const scopes=new Set(rows.filter(i=>sameTarget(s,i)).map(i=>i.scope));const procedures=s.procedures.filter(p=>scopes.has(p.scope));if(!procedures.length)text($('procedures'),'p','No repair is qualified for automatic reuse on this gateway yet.');for(const p of procedures){const c=text($('procedures'),'div','','row');text(c,'p','Outgoing port-capacity repair  /  '+(p.status==='validated'?'Approved for matching future incidents':p.status==='suspended'?'Automatic reuse suspended':'Awaiting qualification'));text(c,'small','Promotion requires two distinct verified repairs and your review. A changed gateway identity needs its own qualification.');const name=actor(c,'procedure-'+p.scope);button(c,p.status==='validated'?'Suspend automatic reuse':'Qualify for automatic reuse',()=>decision(p.status==='validated'?'/api/suspend':'/api/promote',{scope:p.scope,cause:p.cause,action:p.action,actor:name.value}),true)}
 $('observations').textContent=JSON.stringify(s.observations,null,2);$('executions').textContent=JSON.stringify(s.executions.slice(-10),null,2);$('audit').textContent=JSON.stringify(s.audit.slice(-15),null,2);for(const e of document.querySelectorAll('details[data-key]'))if(open.has(e.dataset.key))e.open=true;
}
async function refresh(){try{const s=await api('/api/status');$('login').hidden=true;$('content').hidden=false;render(s);if(failed){$('message').textContent='Connection restored.';$('message').className='';failed=false}}catch(e){if(e.status===401){failed=false;return}failed=true;for(const card of $('health').children){card.className='card warn';const status=card.querySelector('strong');if(status)status.textContent='Live status unavailable'}problem('Cannot update the page: '+e.message+'. The last displayed information may be out of date.')}}
refresh();setInterval(refresh,3000);
</script></body></html>'''
